compile.workshop:
variables {
    global:
        0: counter
        1: indexed
    player:
        0: points
}

rule ("Initialize global variables") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(indexed, Array(0));
    }
}

rule ("postfix assignments") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    actions {
        Modify Global Variable(counter, Add, 1);
        Modify Global Variable(counter, Subtract, 1);
        Modify Global Variable At Index(indexed, 0, Add, 1);
        Modify Global Variable At Index(indexed, 0, Subtract, 1);
        Modify Player Variable(Event Player, points, Add, 1);
        Modify Player Variable(Event Player, points, Subtract, 1);
    }
}

